"""Alerts router — real-time alert stream and Supabase alert history."""
from __future__ import annotations

import asyncio
import json
from collections import deque
from datetime import datetime, timezone
from typing import Deque

from fastapi import APIRouter, HTTPException, Query
from fastapi.responses import StreamingResponse

from database.connection import get_supabase
from schemas.models import AlertEvent
from services.data_simulator import simulator

router = APIRouter(prefix="/alerts", tags=["alerts"])

# In-process buffer of alerts generated by the simulator
_alert_buffer: Deque[AlertEvent] = deque(maxlen=200)


def _on_alert(alert: AlertEvent) -> None:
    _alert_buffer.appendleft(alert)


# Register callback once (module-level)
simulator.register_alert_callback(_on_alert)


@router.get("/recent", response_model=list[AlertEvent])
def get_recent_alerts(limit: int = Query(50, ge=1, le=200)):
    """Return the most recent in-memory alerts (from this session)."""
    return list(_alert_buffer)[:limit]


@router.get("/db", response_model=list[dict])
def get_db_alerts(
    limit: int = Query(50, ge=1, le=500),
    resolved: bool | None = Query(None),
):
    """Fetch alerts stored in Supabase."""
    try:
        db = get_supabase()
        q = (
            db.table("alerts")
            .select("*")
            .order("created_at", desc=True)
            .limit(limit)
        )
        if resolved is not None:
            q = q.eq("resolved", resolved)
        return q.execute().data or []
    except Exception as exc:
        raise HTTPException(status_code=500, detail=str(exc))


@router.get("/stream")
async def stream_alerts():
    """
    Server-Sent Events (SSE) endpoint.
    The React frontend can subscribe to this for real-time alert push
    without a WebSocket library.
    """
    async def event_generator():
        last_seen: int = 0
        while True:
            current = list(_alert_buffer)
            new_events = current[:max(0, len(current) - last_seen)]
            for ev in reversed(new_events):
                payload = ev.model_dump(mode="json")
                payload["created_at"] = payload["created_at"].isoformat() \
                    if isinstance(payload["created_at"], datetime) else payload["created_at"]
                yield f"data: {json.dumps(payload)}\n\n"
            last_seen = len(current)
            await asyncio.sleep(5)

    return StreamingResponse(event_generator(), media_type="text/event-stream")
